#include <vector>
#include <cstddef>
#include <cmath>
#include <omp.h>

struct COOElement {
    size_t row, column;
    double value;
};

/* Solve the sparse linear system Ax=b for x.
   A is a sparse NxN matrix in COO format. x and b are dense vectors with N elements.
   Use OpenMP to compute in parallel.
   Example:

   input: A=[{0,0,1}, {0,1,1}, {1,1,-2}] b=[1,4]
   output: x=[3,-2]
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    const double eps = 1e-12;

    if (b.size() < N) {
        x.clear();
        return;
    }

    // Build a dense augmented matrix [A | b].
    // Parallelize over COO entries using thread-private accumulation buffers to avoid races.
    std::vector<std::vector<double>> denseA(N, std::vector<double>(N, 0.0));

    int max_threads = omp_get_max_threads();
    std::vector<std::vector<double>> local_accum(
        static_cast<size_t>(max_threads),
        std::vector<double>(N * N, 0.0)
    );

    #pragma omp parallel
    {
        int tid = omp_get_thread_num();
        std::vector<double>& local = local_accum[static_cast<size_t>(tid)];

        #pragma omp for schedule(static)
        for (size_t k = 0; k < A.size(); ++k) {
            const COOElement& e = A[k];
            if (e.row < N && e.column < N) {
                local[e.row * N + e.column] += e.value;
            }
        }
    }

    #pragma omp parallel for schedule(static)
    for (size_t i = 0; i < N; ++i) {
        for (size_t j = 0; j < N; ++j) {
            double sum = 0.0;
            for (int t = 0; t < max_threads; ++t) {
                sum += local_accum[static_cast<size_t>(t)][i * N + j];
            }
            denseA[i][j] = sum;
        }
    }

    std::vector<double> rhs(N);
    #pragma omp parallel for schedule(static)
    for (size_t i = 0; i < N; ++i) {
        rhs[i] = b[i];
    }

    x.assign(N, 0.0);

    // Gaussian elimination with partial pivoting.
    for (size_t k = 0; k < N; ++k) {
        // Find pivot row sequentially for determinism and simplicity.
        size_t pivot = k;
        double max_val = std::fabs(denseA[k][k]);
        for (size_t i = k + 1; i < N; ++i) {
            double v = std::fabs(denseA[i][k]);
            if (v > max_val) {
                max_val = v;
                pivot = i;
            }
        }

        if (max_val < eps) {
            // Singular or nearly singular matrix.
            x.assign(N, 0.0);
            return;
        }

        if (pivot != k) {
            std::swap(denseA[k], denseA[pivot]);
            std::swap(rhs[k], rhs[pivot]);
        }

        const double pivot_val = denseA[k][k];

        // Eliminate rows below pivot in parallel. Each thread owns a distinct row i.
        #pragma omp parallel for schedule(static)
        for (size_t i = k + 1; i < N; ++i) {
            double factor = denseA[i][k] / pivot_val;
            denseA[i][k] = 0.0;
            for (size_t j = k + 1; j < N; ++j) {
                denseA[i][j] -= factor * denseA[k][j];
            }
            rhs[i] -= factor * rhs[k];
        }
    }

    // Back substitution.
    for (size_t ii = N; ii-- > 0;) {
        double sum = 0.0;

        #pragma omp parallel for reduction(+:sum) schedule(static)
        for (size_t j = ii + 1; j < N; ++j) {
            sum += denseA[ii][j] * x[j];
        }

        if (std::fabs(denseA[ii][ii]) < eps) {
            x.assign(N, 0.0);
            return;
        }

        x[ii] = (rhs[ii] - sum) / denseA[ii][ii];
    }
}
